),
array(
'pos'=>13,
'title'=>'Queso Cabrales DOP: qué es, cómo se madura en cueva y cómo reconocerlo',
'slug'=>'queso-cabrales-dop-que-es-maduracion-cueva-como-reconocerlo',
'en_title'=>'Cabrales PDO cheese: what it is, cave maturation and how to identify it',
'en_slug'=>'cabrales-pdo-cheese-what-it-is-cave-maturation-how-identify',
'excerpt'=>'Guía completa del Cabrales DOP: leche cruda, mohos azules, cuevas de maduración, territorio, sabor y elementos para reconocer una pieza auténtica.',
'en_excerpt'=>'Complete guide to Cabrales PDO: raw milk, blue mould, cave maturation, territory, flavour and how to identify authentic cheese.',
'lead_es'=>'Cabrales es uno de los quesos azules españoles más reconocibles, pero su singularidad no procede simplemente de tener vetas azul-verdosas. La DOP vincula leche cruda de la zona, elaboración local y maduración en cuevas naturales de los Picos de Europa, donde humedad y temperatura favorecen el desarrollo de Penicillium. Además, puede elaborarse solo con leche de vaca o con mezclas autorizadas que incorporan oveja y cabra, lo que explica parte de la variación entre piezas.',
'lead_en'=>'Cabrales is one of Spain’s most recognisable blue cheeses, but its identity comes from far more than blue-green veining. The PDO connects raw local milk, local production and maturation in natural caves in the Picos de Europa, where humidity and temperature favour Penicillium development. It may be made from cow milk alone or authorised combinations including sheep and goat milk, helping explain variation between cheeses.',
'facts_es'=>array(array('Leche','Cruda de vaca o mezcla autorizada de vaca, oveja y cabra.'),array('Maduración','En cuevas naturales de la zona; el consejo regulador describe periodos habituales de dos a cuatro meses.'),array('Moho','Penicillium desarrollado durante la maduración produce las vetas azul-verdosas.'),array('Identificación','Envase, etiqueta del elaborador y contraetiqueta numerada de la DOP.')),
'facts_en'=>array(array('Milk','Raw cow milk or an authorised combination of cow, sheep and goat milk.'),array('Maturation','In natural caves in the area; the regulatory council describes typical periods of two to four months.'),array('Mould','Penicillium developing during maturation creates the blue-green veins.'),array('Identification','Packaging, producer label and numbered PDO control label.')),
'sections_es'=>array(
array('Qué hace que un azul sea Cabrales','No todo queso azul asturiano es Cabrales. La denominación fija una zona de producción y una forma de elaboración vinculada a municipios concretos. La leche procede de ganaderías controladas de esa área y el queso debe seguir el proceso certificado, incluida la fase que más lo distingue: la maduración en cuevas naturales.\n\nLa protección del nombre es importante porque el aspecto visual de muchos azules puede ser parecido. Las vetas no bastan para identificar origen; la trazabilidad y la contraetiqueta son las que convierten una pieza en DOP Cabrales.'),
array('Una particularidad: puede cambiar la mezcla de leches','El Cabrales actual puede elaborarse con leche cruda de vaca o con mezcla de dos o tres especies entre vaca, oveja y cabra, conforme a las condiciones de la DOP. Históricamente, la mezcla reflejaba la disponibilidad de leche de los rebaños de montaña. En épocas del año con menos producción de oveja y cabra, la leche de vaca adquiere mayor protagonismo.\n\nEsta variación ayuda a explicar diferencias de intensidad, grasa, aroma y textura entre productores y lotes. No debe interpretarse como inconsistencia: forma parte del marco tradicional permitido por la denominación.'),
array('Qué ocurre dentro de las cuevas','Tras la elaboración y el oreo, los quesos pasan a cuevas naturales. El Consejo Regulador señala humedades muy elevadas, alrededor del 90 %, y temperaturas frescas que favorecen el desarrollo de los mohos. El ambiente permite que Penicillium colonice la pasta y genere las características zonas azul-verdosas.\n\nLa cueva no actúa como una simple nevera. Humedad, circulación de aire, manejo y tiempo condicionan proteólisis, textura y aroma. Por eso la maduración es una parte central de la identidad del Cabrales y no un detalle añadido después de fabricar un queso azul genérico.'),
array('Textura, aroma y picor','Un Cabrales bien madurado presenta una pasta untuosa o cremosa en distinto grado, con vetas de moho distribuidas por el interior. El perfil es intenso y persistente, con salinidad, notas lácticas evolucionadas, humedad de cueva, moho noble y un picor que puede aumentar según composición y maduración. Las piezas con presencia de leche de cabra u oveja pueden mostrar un carácter especialmente marcado.\n\nUn aroma potente no debe confundirse automáticamente con deterioro. En los azules es esencial conocer el estilo normal y distinguir el moho previsto de crecimientos o alteraciones extrañas.'),
array('Cómo servirlo para que no domine toda la degustación','Por su intensidad, el Cabrales funciona bien en pequeñas porciones. Si forma parte de una tabla, suele colocarse hacia el final para que no sature el paladar antes de quesos más delicados. Conviene atemperar solo la cantidad que se va a consumir, porque recién salido del frigorífico la grasa y la textura se perciben más rígidas y el aroma se expresa peor.\n\nTambién puede utilizarse en cocina, pero calentar un Cabrales modifica su perfil y puede amplificar salinidad y aroma. Para degustarlo como queso, una porción moderada y un pan neutro permiten apreciar mejor la pasta.'),
array('Cómo reconocer una pieza auténtica','El Consejo Regulador explica que el Cabrales listo para consumo se comercializa con un sistema de envasado e identificación específico, acompañado de etiqueta del fabricante y contraetiqueta numerada. Comprar piezas sin la identificación correspondiente elimina la garantía de la denominación, aunque se presenten como “queso de Cabrales” de manera informal.\n\nEn venta online, revisa fotografías del envase y la contraetiqueta. También es útil que la ficha indique productor, composición de leches y formato. Cuanta más trazabilidad visible haya, menos dependes de descripciones genéricas como “azul asturiano”.')
),
'sections_en'=>array(
array('What makes a blue cheese Cabrales','Not every Asturian blue cheese is Cabrales. The designation establishes a production area and process linked to specific municipalities. Milk comes from controlled farms within the area and the cheese must follow the certified process, including its most distinctive phase: maturation in natural caves.\n\nProtection of the name matters because many blue cheeses can look similar. Veins alone do not prove origin; traceability and PDO control identification are what make a cheese Cabrales PDO.'),
array('A distinctive feature: milk composition can vary','Modern Cabrales can be made from raw cow milk or an authorised mixture of two or three species among cow, sheep and goat. Historically, this reflected the milk available from mountain herds. During periods with less sheep and goat milk, cow milk naturally becomes more prominent.\n\nThis variation helps explain differences in intensity, fat, aroma and texture between producers and batches. It should not be mistaken for inconsistency; it forms part of the traditional framework permitted by the PDO.'),
array('What happens inside the caves','After production and initial drying, cheeses move into natural caves. The regulatory council describes very high humidity, around 90%, and cool temperatures that favour mould development. Penicillium grows through the paste and creates the characteristic blue-green areas.\n\nA cave is not merely a refrigerator. Humidity, airflow, handling and time shape proteolysis, texture and aroma, making cave maturation central to Cabrales identity rather than a decorative step after producing generic blue cheese.'),
array('Texture, aroma and pungency','Well-matured Cabrales has a paste that can range from cohesive to distinctly creamy, crossed by mould veins. The profile is intense and persistent, with saltiness, evolved dairy notes, cave character, noble mould and varying pungency. Cheeses containing sheep or goat milk may show particularly assertive character.\n\nA powerful aroma should not automatically be confused with spoilage. With blue cheese, knowing the normal style is essential for distinguishing intended mould from unexpected deterioration.'),
array('Serving it without overwhelming the tasting','Because Cabrales is intense, small portions work well. On a cheese board it generally belongs near the end so it does not overwhelm the palate before gentler cheeses. Let only the serving portion lose its refrigerator chill; very cold fat and paste feel firmer and aromas are less expressive.\n\nCabrales also works in cooking, although heat changes its profile and can amplify saltiness and aroma. For tasting the cheese itself, moderate portions and neutral bread make the paste easier to appreciate.'),
array('How to identify an authentic cheese','The regulatory council describes specific packaging and identification for Cabrales ready for sale, together with the producer label and numbered PDO control label. Cheese sold without the corresponding identification does not carry the denomination’s guarantee, even if it is informally described as “Cabrales”.\n\nOnline, inspect packaging and control-label photographs. Producer, milk composition and format are also useful information. The more traceability a product page shows, the less you have to rely on vague phrases such as “Asturian blue”.')
),
'faq_es'=>array(array('¿Cabrales se hace siempre con tres leches?','No. Puede elaborarse solo con leche cruda de vaca o con mezclas autorizadas que incluyan oveja y cabra.'),array('¿Las vetas azules significan que el queso está estropeado?','No en un Cabrales normal. El desarrollo de Penicillium forma parte de la maduración prevista. Lo importante es distinguir ese moho característico de cambios anormales no propios del producto.')),
'faq_en'=>array(array('Is Cabrales always made from three milks?','No. It can be made from raw cow milk alone or authorised mixtures that include sheep and goat milk.'),array('Do blue veins mean the cheese is spoiled?','Not in normal Cabrales. Penicillium development is part of the intended maturation. The key is distinguishing that characteristic mould from abnormal changes.')),
'conclusion_es'=>'Cabrales es un queso de territorio y de cueva tanto como un queso azul. La mezcla posible de leches, la maduración natural y el sistema de identificación explican por qué no basta con mirar las vetas para saber qué estamos comprando.',
'conclusion_en'=>'Cabrales is a cheese of territory and cave as much as it is a blue cheese. Possible milk combinations, natural cave maturation and official identification explain why blue veins alone are not enough to know what you are buying.',
'related'=>array('quesos-dop-espana-que-garantizan-guia-regiones-estilos','como-saber-queso-mal-estado-moho-olor-textura','como-catar-queso-aroma-textura-sabor-intensidad-persistencia','como-preparar-tabla-quesos-cantidades-orden-acompanamientos'),
'sources'=>array('https://www.mapa.gob.es/es/alimentacion/temas/calidad-diferenciada/dop-igp/detalle/queso_lacteo/dop_cabrales','https://www.quesocabrales.org/elaboracion','https://www.quesocabrales.org/pdf/pliego-condiciones-dop-cabrales.pdf')
),
array(
'pos'=>14,
'title'=>'Torta del Casar DOP: qué es, cómo se elabora y cómo servirla',
'slug'=>'torta-del-casar-dop-que-es-como-se-elabora-como-servirla',
'en_title'=>'Torta del Casar PDO: what it is, how it is made and how to serve it',
'en_slug'=>'torta-del-casar-pdo-what-it-is-how-made-how-serve',
'excerpt'=>'Qué hace única a la Torta del Casar DOP: leche cruda de oveja, cuajo vegetal de cardo, maduración, textura cremosa y forma correcta de servirla.',
'en_excerpt'=>'What makes Torta del Casar PDO distinctive: raw sheep milk, cardoon rennet, maturation, creamy texture and the best way to serve it.',
'lead_es'=>'Torta del Casar no es un nombre genérico para cualquier queso extremeño muy cremoso. La DOP protege una elaboración concreta basada en leche cruda de oveja, cuajo vegetal obtenido del cardo Cynara cardunculus y una maduración que transforma la pasta hasta volverla extraordinariamente blanda y fundente. Esa textura, que históricamente podía hacer que la pieza se hundiera bajo su propio peso, es precisamente uno de los rasgos que convirtieron a este queso en una especialidad diferenciada.',
'lead_en'=>'Torta del Casar is not a generic name for any very creamy cheese from Extremadura. The PDO protects a specific method based on raw sheep milk, vegetable rennet from Cynara cardunculus and maturation that transforms the paste until it becomes exceptionally soft and melting. That texture, historically capable of making the cheese sag under its own weight, is one of the features that turned it into a distinctive regional speciality.',
'facts_es'=>array(array('Leche','Cruda de oveja procedente de las razas y rebaños admitidos por la DOP.'),array('Cuajo','Vegetal, obtenido de la flor del cardo Cynara cardunculus.'),array('Maduración','Mínimo de dos meses según el Consejo Regulador.'),array('Textura','Pasta muy blanda, cremosa y untable cuando alcanza el punto característico.')),
'facts_en'=>array(array('Milk','Raw sheep milk from breeds and registered flocks admitted by the PDO.'),array('Rennet','Vegetable rennet obtained from Cynara cardunculus flowers.'),array('Maturation','At least two months according to the regulatory council.'),array('Texture','Very soft, creamy and spreadable when the characteristic stage is reached.')),
'sections_es'=>array(
array('Leche cruda de oveja y territorio','La materia prima procede de ovejas vinculadas a la zona protegida y se utiliza sin pasteurización. Esto exige un manejo higiénico especialmente cuidadoso desde el ordeño hasta la quesería. La leche se conserva refrigerada y su trazabilidad forma parte del sistema de control de la DOP.\n\nEl vínculo territorial no termina en la ganadería. Las industrias queseras inscritas realizan la elaboración y maduración dentro del marco geográfico y técnico previsto. Un queso cremoso de oveja producido fuera de ese sistema puede compartir textura, pero no puede utilizar la denominación Torta del Casar.'),
array('El cardo: por qué el cuajo vegetal importa tanto','La coagulación se realiza con un preparado obtenido de la flor del cardo Cynara cardunculus. Sus enzimas actúan de manera distinta a muchos cuajos animales y contribuyen a la intensa proteólisis que caracteriza la pasta. También se asocian al ligero amargor vegetal que forma parte del perfil tradicional.\n\nNo conviene simplificar diciendo que el cardo “hace líquido” el queso por sí solo. La textura final es el resultado conjunto de leche, coagulación, tamaño del grano, desuerado, prensado, salado, humedad y maduración. El cuajo es decisivo, pero funciona dentro de un proceso completo.'),
array('De la cuajada a una pasta que se vuelve cremosa','Después de coagular, la cuajada se corta finamente, se moldea, se prensa y se sala. A partir de ahí comienza una maduración en condiciones controladas de temperatura y humedad. Durante al menos dos meses, las enzimas transforman las proteínas y la pasta pierde firmeza hasta desarrollar la cremosidad característica.\n\nEn determinadas fases, el interior puede ejercer tanta presión que la corteza todavía blanda necesita apoyo mediante vendas para evitar que la pieza se abra. La forma ligeramente caída que inspira la palabra “torta” no es una estrategia de presentación, sino una consecuencia histórica del comportamiento de la pasta.'),
array('Qué sabor y textura esperar','La Torta del Casar suele ofrecer una pasta de color blanco a marfil, muy cremosa y fundente, con aromas lácticos y vegetales. Su salinidad no debería dominar y puede aparecer un amargor ligero ligado al cuajo vegetal. La intensidad aumenta con el punto de maduración, pero una pieza equilibrada conserva definición y no se reduce a una masa fuerte o salada.\n\nLa textura es parte fundamental de la calidad sensorial. Demasiado fría puede parecer firme y aromáticamente cerrada; excesivamente calentada pierde la estructura que se busca disfrutar.'),
array('Cómo servirla sin estropear el punto','El propio Consejo Regulador recomienda consumirla alrededor de 20–21 °C y evitar calentarla de manera agresiva. En casa, lo más razonable es sacar la cantidad o la pieza con la antelación suficiente para que pierda frío de forma gradual. No hace falta recurrir al microondas para “hacerla cremosa”: una Torta en buen punto debe alcanzar su textura de servicio por atemperado.\n\nLa forma clásica es abrir la parte superior de la corteza como una tapa y acceder a la pasta con pan o una cuchara. Si no se va a consumir entera, conviene volver a proteger bien la abertura y seguir las indicaciones de conservación del productor.'),
array('Cómo reconocer una Torta del Casar auténtica','Busca la denominación completa DOP Torta del Casar y la etiqueta de control correspondiente. El consejo regulador insiste en que esa identificación es la garantía frente a quesos de aspecto similar. En tienda online, una fotografía clara de la etiqueta y una ficha que detalle productor, peso y conservación son señales de una presentación comercial cuidada.\n\nNo todo queso llamado informalmente “torta” está vinculado a Casar de Cáceres. Torta puede describir una familia o aspecto en el lenguaje común; Torta del Casar es un nombre geográfico protegido.')
),
'sections_en'=>array(
array('Raw sheep milk and territory','The raw material comes from sheep linked to the protected area and is used without pasteurisation. This demands careful hygiene from milking through delivery to the dairy. Milk is kept refrigerated and traceability forms part of the PDO control system.\n\nThe territorial link continues beyond farming. Registered dairies carry out production and maturation within the geographical and technical framework. A creamy sheep cheese made elsewhere may share texture, but it cannot use the Torta del Casar name.'),
array('Why cardoon rennet matters','Coagulation uses a preparation obtained from Cynara cardunculus flowers. Its enzymes act differently from many animal rennets and contribute to the intense proteolysis characteristic of the paste. They are also associated with the slight vegetal bitterness that belongs to the traditional profile.\n\nIt would be too simple to say that cardoon alone “liquefies” the cheese. Final texture comes from milk, coagulation, curd size, draining, pressing, salting, humidity and maturation working together. Rennet is decisive, but it operates inside a complete system.'),
array('From curd to a creamy paste','After coagulation the curd is cut finely, moulded, pressed and salted. Maturation then begins under controlled temperature and humidity. Over at least two months, enzymes transform proteins and the paste loses firmness until the characteristic creaminess develops.\n\nAt certain stages the interior can become so soft that the still-delicate rind needs support with bands to prevent splitting. The slightly collapsed form behind the word “torta” is not merely presentation; it reflects the historical behaviour of the cheese.'),
array('What flavour and texture to expect','Torta del Casar generally has a white-to-ivory paste that is highly creamy and melting, with dairy and vegetal aromas. Salt should not dominate, and a slight bitterness associated with vegetable rennet can appear. Intensity varies with maturation, but a balanced cheese retains definition rather than becoming simply strong or salty.\n\nTexture is a central quality. Served too cold, the cheese can seem firm and aromatically closed; heated aggressively, it loses the structure that makes it distinctive.'),
array('How to serve it at the right point','The regulatory council recommends consumption around 20–21°C and advises against aggressive heating. At home, allow the cheese or serving portion to lose its chill gradually. There is no need to microwave it to “make it creamy”: a ripe Torta should reach serving texture through gentle warming at room conditions.\n\nThe classic approach is to cut the top rind like a lid and access the paste with bread or a spoon. If the whole cheese will not be eaten, protect the opening again and follow the producer’s storage instructions.'),
array('How to identify authentic Torta del Casar','Look for the full Torta del Casar PDO name and its control label. The regulatory council presents this identification as the guarantee against similar-looking cheeses. Online, clear label photographs and precise producer, weight and storage information are useful signs of careful retail presentation.\n\nNot every cheese informally called a “torta” is connected to Casar de Cáceres. Torta can be a broad descriptive word; Torta del Casar is a protected geographical name.')
),
'faq_es'=>array(array('¿Hay que calentar la Torta del Casar para que quede líquida?','No. Si está en buen punto, basta con atemperarla gradualmente. El calor agresivo, especialmente el microondas, puede alterar la textura y el perfil aromático.'),array('¿Por qué puede tener un ligero amargor?','El cuajo vegetal de cardo contribuye al perfil característico y puede aportar un matiz ligeramente amargo, que no debe confundirse por sí solo con un defecto.')),
'faq_en'=>array(array('Do you need to heat Torta del Casar to make it runny?','No. A ripe cheese only needs gradual warming from refrigerator temperature. Aggressive heat, especially microwaving, can damage texture and aroma.'),array('Why can it taste slightly bitter?','Cardoon vegetable rennet contributes to the characteristic profile and may add a slight bitterness, which is not by itself a defect.')),
'conclusion_es'=>'Torta del Casar es un buen ejemplo de cómo una DOP reúne materia prima, territorio y tecnología: leche cruda de oveja, cuajo de cardo y una maduración que conduce a una pasta extraordinariamente cremosa. Servirla bien es tan importante como comprar una pieza auténtica.',
'conclusion_en'=>'Torta del Casar shows how a PDO brings together raw material, territory and technology: raw sheep milk, cardoon rennet and maturation leading to an exceptionally creamy paste. Serving it correctly matters almost as much as buying an authentic cheese.',
'related'=>array('quesos-dop-espana-que-garantizan-guia-regiones-estilos','queso-leche-cruda-o-pasteurizada-diferencias-sabor-seguridad','como-cortar-servir-queso-temperatura-cuchillos-presentacion','como-preparar-tabla-quesos-cantidades-orden-acompanamientos'),
'sources'=>array('https://www.mapa.gob.es/es/alimentacion/temas/calidad-diferenciada/dop-igp/detalle/queso_lacteo/dop_queso_torta_casar','https://tortadelcasar.eu/elaboracion/','https://tortadelcasar.eu/que-es/')
),
array(
'pos'=>15,
'title'=>'Queso Mahón-Menorca DOP: origen, tipos, maduración y cómo reconocerlo',
'slug'=>'queso-mahon-menorca-dop-origen-tipos-maduracion-como-reconocerlo',
'en_title'=>'Mahón-Menorca PDO cheese: origin, types, maturation and how to identify it',
'en_slug'=>'mahon-menorca-pdo-cheese-origin-types-maturation-how-identify',
'excerpt'=>'Guía del Queso Mahón-Menorca DOP: leche de vaca, versión artesana, forma característica, maduraciones, corteza y claves de autenticidad.',
'en_excerpt'=>'Guide to Mahón-Menorca PDO: cow milk, artisan version, characteristic shape, maturation, rind and authenticity.',
'lead_es'=>'Mahón-Menorca es un queso profundamente ligado a la isla de Menorca y fácil de reconocer por su forma paralelepipédica de cantos redondeados. Sin embargo, dentro de la DOP conviven estilos diferentes: el Mahón-Menorca puede elaborarse con leche sometida a tratamientos de conservación permitidos, mientras que la mención Artesano identifica piezas elaboradas con leche cruda de la propia explotación y moldeadas tradicionalmente con el fogasser. A ello se suma una evolución muy marcada entre tierno, semicurado y curado.',
'lead_en'=>'Mahón-Menorca is deeply connected to the island of Menorca and is easy to recognise by its squared form with rounded edges. Yet the PDO contains distinct styles: Mahón-Menorca can use milk subjected to permitted conservation treatments, while the Artisan designation identifies cheese made from raw milk from the farm itself and traditionally shaped with a cotton cloth known as a fogasser. Maturation then creates major differences between young, semi-aged and aged cheeses.',
'facts_es'=>array(array('Leche','Entera de vaca procedente de ganaderías de Menorca.'),array('Zona','Producción de leche, elaboración y maduración en la isla de Menorca.'),array('Artesano','Leche cruda de la propia explotación y moldeado tradicional con fogasser.'),array('Maduraciones','Tierno desde 21 días, semicurado desde 60 y curado desde 150 días según el Consejo Regulador.')),
'facts_en'=>array(array('Milk','Whole cow milk from farms in Menorca.'),array('Area','Milk production, cheesemaking and maturation on the island of Menorca.'),array('Artisan','Raw milk from the farm itself and traditional fogasser shaping.'),array('Maturation','Young from 21 days, semi-aged from 60 and aged from 150 days according to the regulatory council.')),
'sections_es'=>array(
array('Una DOP que abarca toda la isla','La zona de producción de la leche, elaboración y maduración es Menorca. Este dato es importante porque el vínculo geográfico afecta a todo el recorrido del queso, no solo a la fase final. La leche procede de ganaderías inscritas, las queserías están controladas y la maduración se realiza también en instalaciones autorizadas dentro de la isla.\n\nLa forma tradicional y el tratamiento de la corteza se entienden mejor cuando se ven como parte de esa cultura quesera insular. La DOP no protege un queso “tipo Mahón” fabricado en cualquier lugar, sino un producto ligado al sistema productivo menorquín.'),
array('Mahón-Menorca y Mahón-Menorca Artesano no son exactamente lo mismo','La DOP distingue la elaboración general de la mención Artesano. En esta última se utiliza leche cruda de la propia explotación y el moldeado se realiza con el fogasser, un lienzo de algodón que envuelve la cuajada. El atado deja en la cara superior una marca característica conocida como mamella.\n\nEn el Mahón-Menorca no artesano la leche puede haber recibido tratamientos de conservación admitidos y pueden utilizarse moldes específicos. Ambos están dentro de la misma DOP, pero la palabra Artesano aporta información técnica real y no debería utilizarse como simple sinónimo de “hecho con cuidado”.'),
array('Por qué el queso es cuadrado','El moldeado histórico mediante tela y prensado dio lugar a una pieza de forma paralelepipédica con cantos y aristas redondeados. En elaboraciones no artesanas se pueden utilizar moldes que reproducen la geometría característica. La forma es una pista visual útil, aunque nunca sustituye a la etiqueta de certificación.\n\nDurante el prensado se elimina suero y la pasta gana cohesión. Después llegan la salmuera, el oreo y la maduración, etapas en las que la superficie comienza a evolucionar y a adquirir el aspecto propio de cada edad.'),
array('Tierno, semicurado y curado: cómo cambia el perfil','El Consejo Regulador presenta el tierno a partir de 21 días, con una pasta más blanda y elástica y aromas lácticos suaves. El semicurado, desde 60 días, gana firmeza y un perfil más definido. El curado, a partir de 150 días, se vuelve mucho más firme, puede quebrarse en escamas y desarrolla sabores y aromas intensos y persistentes.\n\nEstas categorías ayudan a elegir uso. Un tierno puede encajar en bocadillos y consumo diario; un semicurado resulta versátil para tablas; un curado funciona bien en porciones pequeñas cuando se busca concentración.'),
array('La corteza y el tratamiento tradicional','Durante la maduración, las piezas se voltean y se cuida la superficie. En el Mahón-Menorca Artesano es tradicional untar la corteza con aceite de oliva o con mezclas que pueden incluir pimentón, generando tonos anaranjados o pardos. El tratamiento forma parte de la evolución del queso y no debe interpretarse como una simple decoración.\n\nLa corteza también cambia con la edad. Observar color y firmeza ayuda a anticipar la maduración, aunque la ficha del productor y la certificación son referencias más fiables que intentar adivinar meses por el aspecto.'),
array('Cómo reconocer un Mahón-Menorca auténtico','El Consejo Regulador identifica el queso amparado mediante su sello y un número de control. La etiqueta debe permitir reconocer claramente la DOP y, si corresponde, la mención Artesano. En compra online conviene revisar también la maduración, porque pedir “un Mahón” sin especificar tierno, semicurado o curado puede conducir a experiencias muy distintas.\n\nLa combinación útil de datos es DOP + Artesano o no + maduración + productor. Con esos cuatro elementos se entiende mucho mejor qué pieza llegará a casa que con fotografías de la corteza por sí solas.')
),
'sections_en'=>array(
array('A PDO covering the whole island','The milk production, cheesemaking and maturation area is Menorca. This matters because the geographical link applies to the complete journey of the cheese, not only its final stage. Milk comes from registered farms, dairies are controlled and maturation also takes place in authorised facilities on the island.\n\nTraditional shaping and rind treatment make most sense when viewed as part of this island cheesemaking culture. The PDO protects a product tied to Menorca, not a generic “Mahón-style” cheese made elsewhere.'),
array('Mahón-Menorca and Mahón-Menorca Artisan are not identical','The PDO distinguishes the general cheese from the Artisan designation. Artisan cheese uses raw milk from the farm itself and is shaped with a cotton cloth called a fogasser. Tying the cloth leaves a characteristic mark on the upper face known as the mamella.\n\nNon-artisan Mahón-Menorca may use milk subjected to permitted conservation treatments and special moulds. Both belong to the PDO, but “Artisan” communicates a real technical distinction rather than serving as a vague synonym for careful production.'),
array('Why the cheese is square','Historical cloth shaping and pressing produced a parallelepiped form with rounded edges. Non-artisan production may use moulds that reproduce the characteristic geometry. Shape is a useful visual clue but never replaces certification.\n\nPressing removes whey and gives the paste cohesion. Brining, drying and maturation then follow, with the surface gradually developing the appearance associated with each age.'),
array('Young, semi-aged and aged: how the profile changes','The regulatory council presents young cheese from 21 days, with a softer, more elastic paste and gentle dairy aromas. Semi-aged cheese, from 60 days, becomes firmer and more defined. Aged cheese, from 150 days, is much firmer, may break into flakes and develops intense, persistent flavours and aromas.\n\nThese categories also help with use. Young Mahón works easily in sandwiches and everyday eating; semi-aged is versatile on boards; aged cheese suits smaller portions when concentration is the goal.'),
array('The rind and traditional surface treatment','During maturation cheeses are turned and their surfaces are maintained. On Mahón-Menorca Artisan, traditional practice includes rubbing the rind with olive oil or mixtures that may contain paprika, creating orange or brown tones. Surface treatment belongs to the cheese’s development and is more than decoration.\n\nThe rind also changes with age. Colour and firmness can suggest maturity, but producer information and certification are more reliable than trying to guess exact months from appearance.'),
array('How to identify authentic Mahón-Menorca','The regulatory council identifies protected cheese through its seal and control number. Labelling should clearly state the PDO and, where applicable, the Artisan designation. Online, always check maturation too: ordering “Mahón” without specifying young, semi-aged or aged can lead to very different experiences.\n\nThe most useful combination is PDO + Artisan status + age + producer. Those four pieces explain far more about the cheese than rind photographs alone.')
),
'faq_es'=>array(array('¿Mahón-Menorca Artesano significa simplemente que la quesería es pequeña?','No. La mención tiene requisitos concretos, entre ellos leche cruda de la propia explotación y el moldeado tradicional previsto por la DOP.'),array('¿Todo Mahón-Menorca está elaborado con leche cruda?','No. La leche cruda es característica de la versión Artesano; el Mahón-Menorca no artesano puede utilizar leche sometida a tratamientos de conservación admitidos.')),
'faq_en'=>array(array('Does Mahón-Menorca Artisan simply mean the dairy is small?','No. The designation has specific requirements, including raw milk from the farm itself and the traditional shaping method defined by the PDO.'),array('Is all Mahón-Menorca made from raw milk?','No. Raw milk characterises the Artisan version; non-artisan Mahón-Menorca may use milk subjected to permitted conservation treatments.')),
'conclusion_es'=>'Mahón-Menorca ofrece varias experiencias dentro de una misma DOP. Entender la diferencia entre Artesano y no artesano y, sobre todo, leer la maduración permite elegir desde un queso láctico y elástico hasta una pieza firme, compleja y muy persistente.',
'conclusion_en'=>'Mahón-Menorca offers several experiences within one PDO. Understanding Artisan versus non-artisan production and, above all, reading the maturation level lets you choose from a gentle elastic cheese to a firm, complex and highly persistent one.',
'related'=>array('quesos-dop-espana-que-garantizan-guia-regiones-estilos','queso-tierno-semicurado-curado-viejo-anejo-diferencias','queso-leche-cruda-o-pasteurizada-diferencias-sabor-seguridad','como-catar-queso-aroma-textura-sabor-intensidad-persistencia'),
'sources'=>array('https://www.mapa.gob.es/es/alimentacion/temas/calidad-diferenciada/dop-igp/detalle/queso_lacteo/dop_mahon_menorca','https://quesomahonmenorca.com/nuestros-quesos/','https://quesomahonmenorca.com/consejo-regulador/')
),
array(
'pos'=>16,
'title'=>'Queso Majorero DOP: leche de cabra majorera, maduración y tipos de corteza',
'slug'=>'queso-majorero-dop-leche-cabra-majorera-maduracion-tipos-corteza',
'en_title'=>'Majorero PDO cheese: Majorera goat milk, maturation and rind styles',
'en_slug'=>'majorero-pdo-cheese-majorera-goat-milk-maturation-rind-styles',
'excerpt'=>'Qué define al Queso Majorero DOP de Fuerteventura: cabra majorera, posibles mezclas autorizadas, maduración y cortezas con aceite, pimentón o gofio.',
'en_excerpt'=>'What defines Majorero PDO from Fuerteventura: Majorera goat milk, authorised additions, maturation and rinds with oil, paprika or gofio.',
'lead_es'=>'El Queso Majorero es una de las expresiones más claras de la relación entre una raza ganadera y un territorio insular. La DOP se elabora en Fuerteventura a partir de leche de cabra majorera y, en quesos destinados a maduración, puede admitir una proporción limitada de leche de oveja canaria. Además, la corteza puede tratarse con aceite, pimentón o gofio, creando versiones visual y sensorialmente distintas sin dejar de pertenecer a la misma denominación.',
'lead_en'=>'Majorero is one of the clearest examples of a cheese linking a livestock breed to an island territory. The PDO is produced in Fuerteventura from Majorera goat milk and, for cheeses destined for maturation, may allow a limited proportion of Canary sheep milk. The rind can also be treated with oil, paprika or gofio, creating visually and sensorially different versions within the same designation.',
'facts_es'=>array(array('Leche','Principalmente cabra majorera; en queso para madurar puede añadirse hasta el límite autorizado de leche de oveja canaria.'),array('Zona','Producción y maduración en Fuerteventura.'),array('Maduración','Tierno 8–20 días, semicurado 21–60 y curado más de 60 días según el Consejo Regulador.'),array('Corteza','Puede presentarse natural o untada con aceite, pimentón o gofio según el estilo.')),
'facts_en'=>array(array('Milk','Primarily Majorera goat; cheese for maturation may include Canary sheep milk up to the authorised limit.'),array('Area','Production and maturation in Fuerteventura.'),array('Maturation','Young 8–20 days, semi-aged 21–60, aged over 60 days according to the regulatory council.'),array('Rind','May be natural or rubbed with oil, paprika or gofio depending on style.')),
'sections_es'=>array(
array('La cabra majorera y el paisaje de Fuerteventura','La cabra majorera está adaptada a las condiciones áridas de Fuerteventura y constituye la base de la denominación. Su importancia no es solo cultural: la DOP define la leche de esta raza como materia prima principal y relaciona el queso con una ganadería capaz de desarrollarse en un entorno de baja pluviometría y recursos forrajeros particulares.\n\nCuando se habla de “queso de cabra canario” se engloba un mundo muy amplio. Queso Majorero es una denominación concreta, ligada a Fuerteventura, a ganaderías controladas y a requisitos de elaboración y maduración propios.'),
array('¿Es siempre 100 % leche de cabra?','En las piezas puede haber un matiz importante. El Consejo Regulador explica que el Majorero se elabora con leche de cabra majorera y que, cuando se destina a maduración, puede incorporarse hasta un máximo permitido de leche de oveja canaria. Por eso conviene leer la etiqueta de una pieza concreta en lugar de asumir que todas las referencias tienen idéntica composición.\n\nLa posible adición no transforma el queso en una mezcla genérica: sigue estando regulada dentro del pliego y ligada a especies y porcentajes concretos.'),
array('Pasta prensada y evolución con la maduración','El Majorero es un queso de coagulación enzimática y pasta prensada. El prensado expulsa suero y crea una estructura compacta que evoluciona después en cámara. La DOP contempla desde quesos tiernos de pocos días hasta semicurados y curados de más de 60 días.\n\nA medida que avanza la maduración, la pasta pierde humedad, aumenta la firmeza y se concentran los sabores. Un tierno puede resultar más láctico y flexible; un curado muestra una textura más compacta y un carácter caprino más persistente.'),
array('Aceite, pimentón y gofio: tres formas de trabajar la superficie','Una de las imágenes más características del Majorero son sus cortezas tratadas. El aceite mantiene un aspecto relativamente natural; el pimentón aporta tonos rojizos y su propio matiz aromático; el gofio, harina de cereal tostado profundamente vinculada a Canarias, crea una superficie más oscura y un perfil tostado particular.\n\nEstos tratamientos no deberían utilizarse como sustituto de la información de maduración. Dos quesos con pimentón pueden tener edades distintas y, por tanto, texturas y sabores muy diferentes. La corteza describe una capa del producto, no todo el queso.'),
array('Qué perfil esperar','La pasta suele ser compacta y cremosa en grados variables, con acidez característica y un picor que puede crecer en piezas más evolucionadas. La leche de cabra aporta un perfil distinto al de los quesos de oveja o vaca, pero el resultado final también depende del afinado y del tratamiento superficial.\n\nEn una cata comparativa, probar versiones con aceite, pimentón y gofio de maduración semejante permite entender mejor qué aporta realmente cada corteza. Si cambia también la edad, resulta difícil separar ambas variables.'),
array('Cómo reconocer la DOP al comprar','La etiqueta debe mostrar la denominación Queso Majorero DOP y su sistema de identificación. En internet, busca también isla de producción, productor y maduración. Términos como “majorero” utilizados en sentido coloquial o una corteza de gofio no son por sí solos prueba de certificación.\n\nPara elegir, define primero si quieres tierno, semicurado o curado y después el tratamiento de superficie. Ese orden evita comprar por color una pieza cuya textura no encaja con lo que buscabas.')
),
'sections_en'=>array(
array('The Majorera goat and Fuerteventura landscape','The Majorera goat is adapted to Fuerteventura’s arid conditions and sits at the centre of the designation. Its importance is not merely cultural: the PDO defines milk from this breed as its main raw material and links the cheese to livestock systems developed under low rainfall and distinctive forage conditions.\n\n“Canary goat cheese” covers a broad world. Majorero is a specific designation tied to Fuerteventura, controlled farms and its own production and maturation rules.'),
array('Is it always 100% goat milk?','There is an important nuance. The regulatory council explains that Majorero is made from Majorera goat milk and that cheese destined for maturation may contain up to the authorised maximum of Canary sheep milk. Reading the label of the specific cheese is therefore more accurate than assuming every reference has identical composition.\n\nThis permitted addition does not make Majorero a generic mixed-milk cheese: it remains regulated within the PDO with defined species and limits.'),
array('Pressed body and maturation','Majorero is an enzymatically coagulated, pressed cheese. Pressing removes whey and creates a compact structure that then evolves in the maturation room. The PDO spans young cheeses of only a few days through semi-aged and aged cheeses of more than 60 days.\n\nAs maturation advances, moisture decreases, firmness increases and flavours concentrate. Young Majorero can feel more lactic and flexible; aged cheese shows a denser texture and more persistent goat character.'),
array('Oil, paprika and gofio: three rind approaches','Some of the most recognisable Majorero cheeses have treated rinds. Oil leaves a relatively natural appearance; paprika adds reddish tones and its own aromatic contribution; gofio, toasted cereal flour deeply linked to Canary food culture, creates a darker surface and distinctive toasted note.\n\nThese treatments should not replace age information. Two paprika-coated cheeses can have different maturities and therefore very different textures and flavours. Rind describes one layer of the cheese, not the whole product.'),
array('What profile to expect','The paste is generally compact and creamy to varying degrees, with characteristic acidity and possible pungency that grows in more mature cheeses. Goat milk brings a profile distinct from sheep or cow cheeses, but maturation and surface treatment also shape the final result.\n\nA useful tasting is to compare oil, paprika and gofio versions at similar ages. If age changes at the same time, it becomes much harder to understand what the rind itself contributes.'),
array('How to identify the PDO when buying','Labelling should show Majorero PDO and its official identification system. Online, look for island of production, producer and maturation as well. The informal use of “Majorero” or a gofio-coated rind is not proof of certification by itself.\n\nChoose age first—young, semi-aged or aged—then surface treatment. That order prevents buying by rind colour only and ending up with a texture you did not want.')
),
'faq_es'=>array(), 'faq_en'=>array(),
'conclusion_es'=>'El Majorero se entiende a partir de tres ejes: la cabra majorera, Fuerteventura y la combinación de maduración con tratamiento de corteza. Leer esos datos juntos permite descubrir diferencias reales dentro de la DOP sin reducir el queso al color exterior.',
'conclusion_en'=>'Majorero is best understood through three axes: the Majorera goat, Fuerteventura, and the combination of maturation with rind treatment. Reading them together reveals real differences inside the PDO without reducing the cheese to its exterior colour.',
'related'=>array('quesos-dop-espana-que-garantizan-guia-regiones-estilos','queso-oveja-cabra-vaca-diferencias-como-elegir','queso-tierno-semicurado-curado-viejo-anejo-diferencias','como-catar-queso-aroma-textura-sabor-intensidad-persistencia'),
'sources'=>array('https://www.mapa.gob.es/es/alimentacion/temas/calidad-diferenciada/dop-igp/detalle/queso_lacteo/dop_queso_majorero','https://quesomajorero.es/queso-majorero','https://quesomajorero.es/consejo-regulador')
),
array(
'pos'=>17,
'title'=>'Queso Tetilla DOP: qué es, cómo se elabora y qué perfil tiene',
'slug'=>'queso-tetilla-dop-que-es-como-se-elabora-perfil',
'en_title'=>'Tetilla PDO cheese: what it is, how it is made and what it tastes like',
'en_slug'=>'tetilla-pdo-cheese-what-it-is-how-made-flavour-profile',
'excerpt'=>'Guía del Queso Tetilla DOP de Galicia: leche de vaca, forma cónica característica, pasta blanda, maduración, sabor y autenticidad.',
'en_excerpt'=>'Guide to Galicia’s Tetilla PDO: cow milk, characteristic conical shape, soft body, maturation, flavour and authenticity.',
'lead_es'=>'Queso Tetilla es uno de los quesos gallegos más reconocibles por su silueta cónica, pero la forma no es un recurso de marketing aislado. La DOP establece una zona, una materia prima basada en leche de vaca de razas admitidas y unas características de corteza, pasta, tamaño y perfil sensorial. El resultado es un queso de textura blanda y cremosa, sabor lácteo y relativamente suave, muy diferente de la idea de que todo queso con denominación de origen debe ser intenso o de larga maduración.',
'lead_en'=>'Tetilla is one of Galicia’s most recognisable cheeses because of its conical shape, but that form is not a marketing gimmick. The PDO establishes an area, cow milk from admitted breeds and defined characteristics for rind, paste, size and sensory profile. The result is a soft, creamy, relatively gentle dairy cheese—very different from the assumption that every protected cheese must be strong or long-aged.',
'facts_es'=>array(array('Leche','Vaca de razas admitidas por la DOP, entre ellas Rubia Gallega, Frisona y Pardo Alpina o sus cruces.'),array('Forma','Cónica, cóncava-convexa, característica de la denominación.'),array('Pasta','Blanda, cremosa y uniforme.'),array('Sabor','Lácteo, mantecoso, ligeramente ácido y con salado suave.')),
'facts_en'=>array(array('Milk','Cow milk from breeds admitted by the PDO, including Rubia Gallega, Friesian and Brown Swiss or their crosses.'),array('Shape','Distinctive conical, concave-convex form.'),array('Paste','Soft, creamy and even.'),array('Flavour','Dairy, buttery, slightly acidic and gently salted.')),
'sections_es'=>array(
array('Galicia, leche de vaca y una identidad propia','Galicia es una región de enorme peso lechero y Queso Tetilla utiliza leche de vaca procedente de ganaderías inscritas y razas contempladas por el pliego. El Consejo Regulador menciona Rubia Gallega, Frisona y Pardo Alpina, además de sus cruces. La alimentación y manejo del ganado forman parte del contexto productivo que sostiene la materia prima.\n\nEl queso se elabora y madura dentro de la zona establecida. Esto significa que una pieza con la misma forma fabricada en otro territorio no se convierte en Queso Tetilla por copiar la silueta.'),
array('De dónde viene la forma tan característica','La forma cónica con lados suavemente curvados es la señal visual más evidente de la DOP. Históricamente ha dado lugar al nombre popular del queso y hoy está definida dentro de sus características. Sin embargo, forma y autenticidad no son sinónimos: el molde puede imitarse, la certificación no.\n\nAl comprar, la silueta sirve para reconocer rápidamente la familia, pero hay que confirmar etiqueta y contraetiqueta. Es el mismo principio que con otros productos protegidos: la apariencia orienta, el sistema de control garantiza.'),
array('Cómo se construye una pasta blanda y cremosa','La leche se coagula, la cuajada se corta y se trabaja para retirar una parte del suero sin perseguir la deshidratación extrema de un queso duro. El moldeado y prensado son compatibles con una pasta que conserva suficiente humedad para mantenerse blanda. Después, salado y maduración terminan de desarrollar estructura y aroma.\n\nEse equilibrio de humedad explica por qué el Queso Tetilla resulta flexible y cremoso. También significa que su conservación debe tratarse con más cuidado que la de un curado muy seco una vez abierta la pieza.'),
array('Qué perfil sensorial esperar','El Consejo Regulador describe una corteza fina y elástica, sin mohos, y una pasta blanca-marfil a amarillenta, blanda, cremosa y uniforme. El aroma es suave y lácteo; en boca aparecen mantequilla, una acidez ligera y una salinidad contenida. No es un queso diseñado para competir por potencia con un azul o un viejo de oveja.\n\nSu valor está precisamente en el equilibrio y la accesibilidad. En una tabla puede funcionar al principio de la degustación, antes de quesos más curados o intensos.'),
array('Cómo utilizarlo en cocina y servicio','La textura facilita cortes en porciones, bocadillos y preparaciones donde se busca fundencia sin una salinidad excesiva. Si se sirve solo, conviene dejar que la porción pierda el frío intenso para recuperar mejor su textura y aroma. No necesita acompañamientos muy dulces o fuertes para resultar interesante.\n\nEn una tabla, combina bien como contrapunto de quesos secos y concentrados. Su presencia aporta variación de humedad y leche incluso cuando no es la pieza más aromáticamente llamativa.'),
array('Cómo reconocer un Queso Tetilla DOP auténtico','Busca el nombre completo de la DOP y la identificación del Consejo Regulador. Una forma triangular o cónica no basta. La ficha online debería indicar productor, peso y certificación y, cuando sea posible, mostrar la etiqueta.\n\nSi compras por primera vez, no esperes un queso “fuerte” por el hecho de tener DOP. La denominación protege una identidad; en este caso, esa identidad incluye suavidad, textura cremosa y un perfil lácteo bien definido.')
),
'sections_en'=>array(
array('Galicia, cow milk and a distinct identity','Galicia is one of Spain’s major dairy regions, and Tetilla uses cow milk from registered farms and breeds recognised by the specification. The regulatory council lists Rubia Gallega, Friesian and Brown Swiss, as well as their crosses. Feeding and livestock management form part of the productive context behind the milk.\n\nCheese production and maturation take place within the defined area. A cheese made elsewhere does not become Tetilla simply by copying its shape.'),
array('Where the characteristic shape comes in','The conical form with softly curved sides is the PDO’s most obvious visual marker. It historically gave rise to the cheese’s popular name and is now part of its defined characteristics. Yet shape and authenticity are not the same: a mould can imitate a silhouette, but not certification.\n\nWhen buying, shape helps identify the family quickly, but label and control identification should confirm it. Appearance guides; the control system guarantees.'),
array('How a soft creamy paste is created','Milk is coagulated, the curd is cut and worked to remove part of the whey without pursuing the extreme dehydration of hard cheese. Moulding and pressing are compatible with a paste that retains enough moisture to remain soft. Salting and maturation then finish the structure and aroma.\n\nThis moisture balance explains Tetilla’s flexible, creamy character. It also means an opened cheese needs more careful storage than a very dry aged wheel.'),
array('What sensory profile to expect','The regulatory council describes a thin, elastic, mould-free rind and a white-ivory to yellowish paste that is soft, creamy and even. Aroma is gentle and dairy-led; flavour includes butter, slight acidity and restrained salt. It is not designed to compete for power with blue cheese or long-aged sheep cheese.\n\nIts value lies in balance and accessibility. On a board, Tetilla works naturally near the beginning before more aged or intense cheeses.'),
array('Using it in cooking and service','The texture lends itself to portioning, sandwiches and preparations that need meltability without excessive salt. When served alone, let the portion lose its deepest chill so texture and aroma recover. It does not need aggressively sweet or strong accompaniments to be interesting.\n\nOn a board it can act as a counterpoint to dry, concentrated cheeses, adding moisture and a different milk profile even when it is not the loudest cheese present.'),
array('How to identify authentic Tetilla PDO','Look for the full PDO name and regulatory council identification. A triangular or conical shape is not enough. An online product page should state producer, weight and certification and ideally show the label.\n\nIf buying for the first time, do not expect a “strong” cheese simply because it has a PDO. The designation protects identity; here that identity includes gentleness, creamy texture and a clearly dairy profile.')
),
'faq_es'=>array(), 'faq_en'=>array(),
'conclusion_es'=>'Queso Tetilla demuestra que la personalidad no siempre significa intensidad. Su identidad está en la leche de vaca gallega, la forma característica y una pasta blanda, cremosa y de sabor lácteo. La certificación permite distinguir esa tradición de una simple imitación visual.',
'conclusion_en'=>'Tetilla shows that personality does not always mean intensity. Its identity lies in Galician cow milk, its characteristic form and a soft creamy dairy profile. Certification separates that tradition from a simple visual imitation.',
'related'=>array('quesos-dop-espana-que-garantizan-guia-regiones-estilos','queso-oveja-cabra-vaca-diferencias-como-elegir','como-conservar-queso-correctamente-nevera-envoltorio-temperatura','como-preparar-tabla-quesos-cantidades-orden-acompanamientos'),
'sources'=>array('https://www.mapa.gob.es/es/alimentacion/temas/calidad-diferenciada/dop-igp/detalle/queso_lacteo/dop_queso_tetilla','https://queixotetilla.org/la-calidad-garantizada/','https://queixotetilla.org/un-queso-unico/')
),
array(
'pos'=>18,
'title'=>'Queso de Murcia al Vino DOP: leche de cabra, baños de vino y cómo reconocerlo',
'slug'=>'queso-murcia-al-vino-dop-leche-cabra-banos-vino-como-reconocerlo',
'en_title'=>'Murcia al Vino PDO cheese: goat milk, wine washing and how to identify it',
'en_slug'=>'murcia-al-vino-pdo-cheese-goat-milk-wine-washing-how-identify',
'excerpt'=>'Qué define al Queso de Murcia al Vino DOP: leche de cabra Murciano-Granadina, cuajada lavada, baños de vino tinto, corteza violácea y perfil.',
'en_excerpt'=>'What defines Murcia al Vino PDO: Murciano-Granadina goat milk, washed curd, red-wine bathing, violet rind and flavour profile.',
'lead_es'=>'Queso de Murcia al Vino llama la atención por una corteza granate o violácea que no procede de un colorante decorativo, sino de los baños de vino tinto aplicados durante su elaboración y curación. La DOP combina esa técnica con leche de cabra vinculada a la Región de Murcia y una tecnología de cuajada lavada y prensada. El resultado es un queso donde el vino se percibe especialmente cerca de la corteza, pero no debería borrar el carácter láctico y caprino de la pasta.',
'lead_en'=>'Murcia al Vino immediately stands out for its garnet or violet rind, which is not a decorative colouring but the result of red-wine baths during production and maturation. The PDO combines this technique with goat milk linked to the Region of Murcia and a washed, pressed curd. Wine is most noticeable near the rind, but it should not erase the dairy and goat character of the paste.',
'facts_es'=>array(array('Leche','Cabra Murciano-Granadina conforme al pliego de la DOP.'),array('Técnica distintiva','Cuajada lavada y baños de vino tinto.'),array('Corteza','Color granate-violeáceo natural asociado al vino.'),array('Perfil','Pasta cremosa y fundente, con notas de vino más evidentes cerca de la corteza.')),
'facts_en'=>array(array('Milk','Murciano-Granadina goat milk under the PDO specification.'),array('Distinctive method','Washed curd and red-wine baths.'),array('Rind','Natural garnet-violet colour associated with wine treatment.'),array('Profile','Creamy, melting paste with wine notes more evident near the rind.')),
'sections_es'=>array(
array('La cabra Murciano-Granadina como materia prima','La especificidad empieza en una raza caprina muy vinculada a la Región de Murcia. El pliego destaca una leche rica en materia grasa y proteína, adecuada para construir una pasta cremosa y fundente. La ganadería se desarrolló en un entorno semiárido donde la cabra ha tenido históricamente una gran importancia por su capacidad de adaptación.\n\nLa DOP no protege cualquier queso de cabra bañado en vino. El origen de la leche, la zona, la elaboración y el sistema de control forman parte de la denominación.'),
array('Qué significa que la cuajada sea lavada','Durante la elaboración se retira parte del suero y se incorpora agua en una fase controlada, una técnica conocida como lavado de cuajada. Esto modifica la cantidad de lactosa disponible para las bacterias y puede influir en acidez, textura y evolución posterior. Después la pasta se moldea y se prensa.\n\nEl lavado no debe confundirse con lavar la corteza. Son operaciones diferentes: una actúa sobre la cuajada antes de formar el queso; la otra, los baños de vino, se aplica sobre la superficie y define buena parte de la apariencia final.'),
array('Los baños de vino y la corteza violácea','El rasgo visual más reconocible procede de baños con vino tinto. El contacto repetido colorea la superficie y aporta aromas que se perciben con especial claridad en la zona próxima a la corteza. La tonalidad puede variar entre granate y violácea según lote, vino, tratamiento y maduración.\n\nEl vino no debería convertir el queso en un producto aromatizado de forma artificialmente dominante. La mejor expresión integra corteza y pasta: primero aparece el carácter láctico y caprino, y el vino añade una capa distinta en el exterior.'),
array('Textura y sabor','El pliego y la documentación del Consejo Regulador describen una pasta blanca a marfil, de textura cremosa y fundente, con acidez moderada y aromas que pueden recordar a mantequilla y notas florales. Cerca de la corteza se hacen más evidentes el vino y las levaduras asociadas a su tratamiento.\n\nLa intensidad dependerá del grado de maduración y del formato. Una pieza más evolucionada puede ganar firmeza y persistencia, mientras que otra más joven resaltará la cremosidad y la frescura láctica.'),
array('Cómo servirlo y con qué compararlo','Si se incluye en una tabla, puede ocupar una posición media: tiene más personalidad de corteza que muchos quesos suaves, pero no necesariamente la potencia de un Cabrales o un curado muy viejo. Servir una porción con corteza permite entender el efecto real del vino; comer solo el centro elimina precisamente uno de sus rasgos distintivos.\n\nPara aprender qué aporta el tratamiento, compáralo con otro queso de cabra de maduración semejante y corteza sin vino. Así se separan mejor las diferencias de leche y edad de las generadas por la superficie.'),
array('Cómo reconocer una pieza auténtica','Busca la denominación DOP Queso de Murcia al Vino y su identificación oficial. Una corteza morada no garantiza nada por sí sola: técnicamente es posible bañar otros quesos en vino. La DOP es la que acredita que se cumplen materia prima, origen y método.\n\nEn una tienda online, la ficha debería indicar productor, peso, maduración y certificación. Si solo aparece “queso al vino” sin referencia clara a la DOP, no debe asumirse que es Queso de Murcia al Vino protegido.')
),
'sections_en'=>array(
array('Murciano-Granadina goat milk as raw material','The cheese’s specificity begins with a goat breed closely linked to the Region of Murcia. The specification highlights milk rich in fat and protein, well suited to a creamy, melting paste. Goat farming developed in a semi-arid environment where the animal has long been important for its ability to adapt.\n\nThe PDO does not protect any goat cheese dipped in wine. Milk origin, geographical area, production and the control system are all part of the designation.'),
array('What washed curd means','During production, part of the whey is removed and water is added at a controlled stage, a technique known as curd washing. This changes the lactose available to bacteria and can influence acidity, texture and later development. The curd is then moulded and pressed.\n\nCurd washing should not be confused with washing the rind. They are separate operations: one acts on the curd before the cheese is formed, while the red-wine baths treat the surface.'),
array('Wine baths and the violet rind','The most recognisable visual feature comes from bathing the cheese in red wine. Repeated contact colours the surface and contributes aromas that are particularly noticeable close to the rind. The exact shade can range from garnet to violet according to batch, wine, treatment and maturation.\n\nWine should not turn the cheese into an artificially dominant flavoured product. The best expression integrates rind and paste: dairy and goat character remain present while wine adds another layer at the exterior.'),
array('Texture and flavour','The specification and regulatory material describe a white-to-ivory paste with creamy, melting texture, moderate acidity and aromas that may suggest butter and floral notes. Wine and yeast-related notes become more noticeable near the rind.\n\nIntensity depends on maturation and format. An older cheese may become firmer and more persistent, while a younger one emphasises creaminess and fresh dairy character.'),
array('How to serve it and what to compare it with','On a board, Murcia al Vino can sit in the middle of the sequence: its rind has more personality than many gentle cheeses, but it is not necessarily as powerful as Cabrales or a very old hard cheese. Include some rind in each portion if you want to understand the wine treatment; eating only the centre removes one of the defining features.\n\nTo learn what the surface treatment contributes, compare it with another goat cheese of similar age and an untreated rind. That separates milk and maturation effects from rind effects more clearly.'),
array('How to identify an authentic cheese','Look for the full Murcia al Vino PDO name and official identification. A purple rind proves nothing by itself; other cheeses can technically be washed in wine. The PDO certifies raw material, origin and method.\n\nOnline product pages should state producer, weight, age and certification. If a listing says only “wine cheese” without a clear PDO reference, do not assume it is protected Murcia al Vino.')
),
'faq_es'=>array(array('¿El interior del queso sabe intensamente a vino?','No necesariamente. El efecto del vino es más evidente en la corteza y en la pasta cercana a ella; el centro mantiene con mayor claridad el carácter láctico y caprino.'),array('¿Una corteza morada significa que es DOP Murcia al Vino?','No. La autenticidad depende de la certificación y del cumplimiento del pliego, no solo del color.')),
'faq_en'=>array(array('Does the whole cheese taste strongly of wine?','Not necessarily. Wine influence is strongest at the rind and nearby paste; the centre retains more of the dairy and goat character.'),array('Does a purple rind mean the cheese is Murcia al Vino PDO?','No. Authenticity depends on certification and compliance with the specification, not colour alone.')),
'conclusion_es'=>'Queso de Murcia al Vino es mucho más que un queso de cabra teñido de morado. La raza, la cuajada lavada, los baños de vino y la maduración construyen conjuntamente un estilo en el que la corteza aporta identidad sin borrar la pasta.',
'conclusion_en'=>'Murcia al Vino is much more than goat cheese coloured purple. Breed, washed curd, wine baths and maturation work together to create a style where the rind contributes identity without erasing the paste.',
'related'=>array('quesos-dop-espana-que-garantizan-guia-regiones-estilos','queso-oveja-cabra-vaca-diferencias-como-elegir','como-catar-queso-aroma-textura-sabor-intensidad-persistencia','tipos-de-queso-guia-leche-maduracion-pasta-corteza-elaboracion'),
'sources'=>array('https://www.mapa.gob.es/es/alimentacion/temas/calidad-diferenciada/dop-igp/detalle/queso_lacteo/dop_qmurciavino','https://quesosdemurcia.com/pdf/normativa/pliego-dop-quesos-de-murcia-al-vino.pdf')
),
array(
'pos'=>19,
'title'=>'Cómo se hace el queso: de la leche a la cuajada, el prensado y la maduración',
'slug'=>'como-se-hace-queso-leche-cuajada-prensado-maduracion',
'en_title'=>'How cheese is made: from milk and curd to pressing and maturation',
'en_slug'=>'how-cheese-is-made-milk-curd-pressing-maturation',
'excerpt'=>'Guía completa del proceso de elaboración del queso: tratamiento de la leche, fermentos, coagulación, corte, desuerado, moldeado, salado y maduración.',
'en_excerpt'=>'Complete guide to cheesemaking: milk treatment, cultures, coagulation, cutting, draining, moulding, salting and maturation.',
'lead_es'=>'Todos los quesos nacen de una idea parecida —concentrar los componentes sólidos de la leche y controlar su transformación—, pero pequeñas decisiones en cada etapa crean productos radicalmente distintos. Temperatura, fermentos, tipo de cuajo, tamaño del grano, cantidad de suero eliminado, prensado, sal, humedad y maduración pueden llevar la misma materia prima hacia un fresco, una pasta blanda, un queso azul o un curado duro. Entender el proceso ayuda mucho más a leer un queso que memorizar categorías aisladas.',
'lead_en'=>'All cheeses begin with a similar idea—concentrating milk solids and controlling their transformation—but small decisions at every stage create radically different products. Temperature, cultures, coagulant, curd size, whey removal, pressing, salt, humidity and maturation can take similar milk toward fresh cheese, soft-ripened cheese, blue cheese or a hard aged wheel. Understanding the process is far more useful than memorising isolated categories.',
'facts_es'=>array(array('Punto de partida','Leche, con tratamiento y composición adecuados al estilo.'),array('Transformación clave','Coagular para formar una red de proteínas que atrapa grasa y agua.'),array('Control de humedad','Corte de cuajada, calentamiento, agitación, desuerado y prensado.'),array('Después','Salado y, en quesos madurados, tiempo bajo condiciones controladas.')),
'facts_en'=>array(array('Starting point','Milk, treated and composed according to the intended style.'),array('Key transformation','Coagulation forms a protein network trapping fat and water.'),array('Moisture control','Curd cutting, heating, stirring, draining and pressing.'),array('Afterwards','Salting and, for ripened cheese, time under controlled conditions.')),
'sections_es'=>array(
array('1. La leche: la receta empieza antes del cuajo','Especie animal, estación, alimentación, grasa, proteína y calidad microbiológica condicionan la materia prima. Después la quesería decide si trabaja con leche cruda o con un tratamiento térmico permitido. La pasteurización reduce microorganismos y estandariza parte de la flora inicial; la leche cruda conserva una comunidad microbiana más diversa y exige un control especialmente riguroso.\n\nNinguna de las dos opciones determina por sí sola la calidad. El queso final depende de cómo se integre la leche con fermentos, tecnología, higiene y maduración.'),
array('2. Fermentos y acidificación','Los cultivos lácticos transforman lactosa en ácido láctico y ayudan a controlar pH, textura, seguridad y desarrollo aromático. Diferentes bacterias trabajan mejor a distintas temperaturas y generan perfiles distintos. En algunos quesos también intervienen mohos y levaduras que actuarán en la superficie o en el interior durante la maduración.\n\nLa acidificación es una especie de reloj interno del proceso. Si avanza demasiado deprisa o demasiado despacio, cambia la forma en que la cuajada expulsa suero y la textura posterior.'),
array('3. Coagulación: convertir leche líquida en una red sólida','El coagulante modifica las proteínas de la leche para formar una cuajada. Puede utilizarse cuajo animal, enzimas microbianas o vegetales según el queso. La coagulación enzimática es común en muchos quesos madurados; en otros estilos tiene gran importancia la coagulación ácida. Torta del Casar muestra cómo un coagulante vegetal de cardo puede formar parte esencial de la identidad de una DOP.\n\nLa firmeza de la cuajada en el momento del corte es crítica: si se rompe demasiado pronto o se deja evolucionar demasiado, cambia la pérdida de humedad.'),
array('4. Corte de la cuajada y desuerado: aquí se decide mucha textura','Cortar la cuajada aumenta la superficie por la que puede salir el suero. Granos pequeños tienden a perder más humedad que bloques grandes. Además, el quesero puede agitar o calentar la cuajada para favorecer el desuerado. Esta es una de las razones por las que un queso duro no se obtiene simplemente “dejándolo más tiempo”: ya desde la cuba se construye una pasta con menos agua.\n\nEl suero separado contiene agua, lactosa y proteínas solubles. La cantidad retenida en la masa influirá en fermentación, elasticidad y vida útil.'),
array('5. Moldeado, prensado y salado','La cuajada se introduce en moldes para adquirir forma. Algunos quesos apenas se prensan; otros reciben presión intensa para expulsar suero y cerrar la pasta. Las marcas del molde o de telas tradicionales pueden convertirse en rasgos visuales característicos, como ocurre en distintos quesos protegidos.\n\nLa sal puede añadirse directamente o mediante salmuera. No solo da sabor: modifica actividad de agua, formación de corteza, textura y desarrollo microbiano. Una cantidad adecuada forma parte del equilibrio tecnológico del queso.'),
array('6. Maduración: el queso sigue cambiando después de fabricarse','En un queso madurado, bacterias, enzimas, mohos o levaduras continúan transformando proteínas y grasas. La proteólisis ablanda la estructura y crea compuestos aromáticos; la lipólisis libera ácidos grasos que pueden generar notas intensas. Temperatura, humedad y oxígeno determinan qué procesos dominan y a qué velocidad.\n\nUna cámara, una cava y una cueva natural no son entornos equivalentes. Cabrales utiliza cuevas húmedas para desarrollar su azul; una pasta prensada de oveja necesita otra evolución; una corteza florida trabaja desde la superficie hacia el interior.'),
array('Por qué dos quesos con la misma leche pueden ser opuestos','Imagina dos quesos de vaca. En uno, la cuajada se corta grande, retiene humedad y madura con flora superficial; en otro se corta fina, se calienta, se prensa y madura durante meses. La especie de leche es idéntica, pero textura, aroma y conservación terminan siendo muy distintos.\n\nPor eso, al leer una ficha, conviene combinar leche con tratamiento, tipo de pasta, maduración y corteza. Esa información cuenta la historia tecnológica del queso mucho mejor que una sola etiqueta comercial.')
),
'sections_en'=>array(
array('1. Milk: the recipe begins before rennet','Animal species, season, feeding, fat, protein and microbiological quality all shape the raw material. The dairy then decides whether to use raw milk or an allowed heat treatment. Pasteurisation reduces microorganisms and standardises part of the initial flora; raw milk retains a more diverse microbial community and demands particularly careful control.\n\nNeither choice determines quality by itself. Final cheese depends on how milk is integrated with cultures, technology, hygiene and maturation.'),
array('2. Cultures and acidification','Lactic cultures turn lactose into lactic acid and help control pH, texture, safety and aromatic development. Different bacteria prefer different temperatures and create different profiles. Some cheeses also use moulds and yeasts that later act at the surface or inside the cheese.\n\nAcidification acts like an internal clock. If it moves too quickly or too slowly, curd drainage and later texture change.'),
array('3. Coagulation: turning liquid milk into a solid network','Coagulants alter milk proteins so a curd can form. Animal rennet, microbial enzymes or vegetable coagulants may be used depending on the cheese. Enzymatic coagulation is common in many matured cheeses, while acid coagulation is important in other styles. Torta del Casar shows how cardoon vegetable rennet can become part of a protected cheese’s identity.\n\nCurd firmness at cutting is critical: cutting too early or too late changes moisture loss.'),
array('4. Cutting and draining: much of texture is decided here','Cutting the curd increases the surface through which whey can leave. Smaller grains generally lose more moisture than large pieces. The cheesemaker may also stir or heat the curd to encourage drainage. This is why hard cheese is not produced simply by “waiting longer”; a lower-moisture body is already being built in the vat.\n\nSeparated whey contains water, lactose and soluble proteins. The amount remaining in the curd influences fermentation, elasticity and shelf life.'),
array('5. Moulding, pressing and salting','Curd goes into moulds to acquire form. Some cheeses receive little pressure; others are strongly pressed to expel whey and close the body. Marks from moulds or traditional cloths can become characteristic visual traits in protected cheeses.\n\nSalt can be applied directly or through brine. It does more than add flavour: it changes water activity, rind formation, texture and microbial development. Appropriate salting is a technological balance.'),
array('6. Maturation: cheese keeps changing after production','In ripened cheese, bacteria, enzymes, moulds and yeasts continue transforming proteins and fats. Proteolysis softens structure and creates flavour compounds; lipolysis releases fatty acids that can produce powerful notes. Temperature, humidity and oxygen determine which processes dominate and how quickly they occur.\n\nA maturation room, cellar and natural cave are not equivalent. Cabrales uses humid caves to develop its blue character; pressed sheep cheese evolves differently; a bloomy rind works from the surface inward.'),
array('Why two cheeses made from the same milk can be opposites','Imagine two cow cheeses. In one, curd is cut large, retains moisture and ripens with surface flora; in the other it is cut finely, heated, pressed and matured for months. Milk species is identical, but texture, aroma and storage behaviour end up completely different.\n\nThat is why a product page should be read as milk + treatment + body + maturation + rind. Together they tell the technological story far better than one marketing label.')
),
'faq_es'=>array(), 'faq_en'=>array(),
'conclusion_es'=>'Hacer queso consiste, en gran parte, en controlar agua, acidez y microorganismos a lo largo del tiempo. Las diferencias entre estilos nacen mucho antes de la maduración: cada decisión desde la leche hasta el corte de la cuajada prepara la textura y el sabor que aparecerán después.',
'conclusion_en'=>'Cheesemaking is largely the controlled management of water, acidity and microorganisms over time. Differences between styles begin long before maturation: every choice from milk through curd cutting prepares the texture and flavour that will emerge later.',
'related'=>array('tipos-de-queso-guia-leche-maduracion-pasta-corteza-elaboracion','queso-leche-cruda-o-pasteurizada-diferencias-sabor-seguridad','queso-tierno-semicurado-curado-viejo-anejo-diferencias','como-catar-queso-aroma-textura-sabor-intensidad-persistencia'),
'sources'=>array('https://www.boe.es/eli/es/rd/2006/09/29/1113/con','https://eur-lex.europa.eu/legal-content/EN/TXT/?uri=CELEX:02004R0853-20240509')
),
array(
'pos'=>20,
'title'=>'Cómo catar queso: aroma, textura, sabor, intensidad y persistencia',
'slug'=>'como-catar-queso-aroma-textura-sabor-intensidad-persistencia',
'en_title'=>'How to taste cheese: aroma, texture, flavour, intensity and persistence',
'en_slug'=>'how-to-taste-cheese-aroma-texture-flavour-intensity-persistence',
'excerpt'=>'Método práctico para catar queso con criterio: preparación, aspecto, aroma, textura, sabores básicos, intensidad, persistencia y cómo comparar piezas.',
'en_excerpt'=>'A practical method for tasting cheese: preparation, appearance, aroma, texture, basic tastes, intensity, persistence and comparison.',
'lead_es'=>'Catar queso no consiste en inventar una lista interminable de aromas sofisticados. Consiste en observar el producto de forma ordenada para separar textura, olor, sabores básicos, aromas retronasales, intensidad y persistencia. Ese método permite comparar quesos con más precisión y, sobre todo, aprender qué te gusta realmente. La clave es describir antes de juzgar: “firme, láctico y ligeramente ácido” aporta más información que limitarse a decir “bueno” o “fuerte”.',
'lead_en'=>'Tasting cheese is not about inventing an endless list of sophisticated aroma notes. It is about observing the product in an orderly way so texture, smell, basic tastes, retronasal aromas, intensity and persistence can be separated. That method makes comparisons more precise and, more importantly, helps you understand what you genuinely enjoy. Description should come before judgement: “firm, dairy and slightly acidic” says far more than simply “good” or “strong”.',
'facts_es'=>array(array('Antes de catar','Atemperar la porción y evitar aromas externos intensos.'),array('Orden','Aspecto → aroma → textura → sabor/aroma en boca → persistencia.'),array('Comparación','Mantener condiciones parecidas y probar de suave a intenso.'),array('Objetivo','Describir con precisión, no adivinar una respuesta correcta.')),
'facts_en'=>array(array('Before tasting','Let the portion lose its chill and avoid strong external aromas.'),array('Order','Appearance → aroma → texture → flavour/in-mouth aroma → persistence.'),array('Comparison','Keep conditions similar and taste from gentle to intense.'),array('Goal','Describe precisely rather than guess a “correct” answer.')),
'sections_es'=>array(
array('Preparar el queso: temperatura, corte y ambiente','El frío reduce la volatilidad de aromas y endurece la grasa. Una porción recién salida de la nevera puede parecer menos aromática y más firme que la misma pieza atemperada. No es necesario dejar horas toda la rueda fuera: basta con cortar lo que se va a degustar y darle tiempo para perder el frío intenso.\n\nUtiliza un cuchillo limpio, evita perfumes, humo o alimentos muy aromáticos cerca y procura que todas las muestras estén en condiciones similares. Si comparas quesos, empieza por los más suaves y termina con azules o piezas muy curadas.'),
array('1. Mirar antes de oler','El aspecto aporta pistas sobre humedad, maduración y tecnología. Observa color de la pasta, distribución de ojos, vetas de moho, grietas, elasticidad visual y relación entre corteza e interior. En un queso azul las vetas son esperables; en una pasta prensada compacta, una estructura completamente distinta es normal.\n\nNo conviertas el color en una puntuación. Un tono más amarillo no significa automáticamente más calidad ni más grasa. Sirve para describir y comparar dentro de un contexto.'),
array('2. Oler: familias aromáticas antes que palabras exactas','Acerca la muestra y busca primero familias generales: láctico, mantequilla, yogur, hierba, heno, frutos secos, animal, fermentado, tierra, bodega, humo, especias o moho noble. Después, si una referencia concreta aparece con claridad, puedes afinar. Es mejor decir “fruto seco tostado” con seguridad que forzarse a identificar una nuez exacta.\n\nLa intensidad del olor también cuenta. Un Queso Tetilla puede ser deliberadamente suave y un Cabrales muy potente; juzgarlos con la misma escala de “cuanto más huele, mejor” no tiene sentido.'),
array('3. Textura: lo que ocurre antes y durante la masticación','Toca y muerde una porción. ¿Es elástica, quebradiza, cremosa, granulosa, adhesiva, fundente, húmeda o seca? ¿Se rompe en lascas o se deforma? La textura conecta directamente con humedad, grasa, proteólisis y tecnología de elaboración.\n\nTambién observa cómo cambia con la temperatura de la boca. Una pasta aparentemente firme puede fundirse rápidamente; otra puede deshacerse en partículas secas. Estas diferencias ayudan a explicar por qué dos quesos de intensidad aromática similar se sienten completamente distintos.'),
array('4. Sabor básico y aroma en boca','Salado, ácido, amargo y dulce pueden aparecer en diferentes proporciones, junto con sensaciones umami y picantes. Después llegan los aromas percibidos retronasalmente al masticar: frutos secos, mantequilla, hierba, cueva, humo, vino, fermentación y muchas otras familias. Conviene separar “sabe salado” de “huele a humo”, porque son percepciones distintas.\n\nUna pequeña acidez puede aportar frescura; un amargor ligero puede ser característico de quesos con cuajo vegetal. La presencia de una sensación no indica por sí sola un defecto: importa si encaja con el estilo y si está equilibrada.'),
array('5. Intensidad, equilibrio y persistencia','La intensidad responde a cuánto impacta el queso; la persistencia, a cuánto tiempo permanece su recuerdo aromático después de tragar. Un queso puede ser intenso pero corto, o moderado y muy persistente. El equilibrio describe cómo se integran sal, acidez, grasa, aroma y posibles notas de corteza o humo.\n\nEsta distinción es útil para comprar. Si te gustan quesos largos pero no agresivos, buscar solo palabras como “fuerte” puede llevarte a piezas equivocadas. Aprende qué dimensión sensorial disfrutas.'),
array('Cómo tomar notas sin convertir la cata en un examen','Una ficha doméstica puede tener seis líneas: aspecto, aroma, textura, sabores, aromas en boca y persistencia. Añade una frase final sobre uso: “lo comería solo”, “funciona mejor en tabla”, “ideal para cocinar” o “demasiado intenso para mí”. Con varias catas empezarás a detectar patrones de preferencia.\n\nNo hace falta acertar descriptores oficiales. La utilidad está en mantener el método. Si hoy llamas “mantequilla” a una nota y mañana la reconoces como “nata”, el aprendizaje sigue siendo válido siempre que compares de forma consistente.'),
array('Cómo comparar dos quesos de forma justa','Cambia una variable cada vez cuando sea posible. Para entender el efecto de la leche, compara tecnologías y edades parecidas. Para entender maduración, prueba el mismo productor en dos edades. Para valorar una corteza de vino o pimentón, compara con una versión similar sin ese tratamiento.\n\nEste enfoque evita conclusiones falsas como “la cabra siempre es más fuerte” después de enfrentar un cabra curado con un vaca fresco. Una buena cata no busca confirmar prejuicios; busca aislar diferencias.')
),
'sections_en'=>array(
array('Preparing cheese: temperature, cut and environment','Cold reduces aroma volatility and firms fat. A portion straight from the refrigerator may seem less aromatic and harder than the same cheese allowed to warm slightly. There is no need to leave an entire wheel out for hours; cut the amount being tasted and let that portion lose its deepest chill.\n\nUse a clean knife, avoid perfume, smoke and powerful food aromas nearby, and keep samples under similar conditions. In comparative tastings, begin with gentle cheeses and end with blue or very mature examples.'),
array('1. Look before smelling','Appearance provides clues about moisture, maturation and technology. Observe paste colour, eye distribution, mould veins, cracks, apparent elasticity and the relationship between rind and interior. Blue veins are expected in blue cheese; a compact pressed cheese naturally has a completely different structure.\n\nDo not turn colour into a score. A more yellow cheese is not automatically better or fattier. Colour is useful for description and comparison within context.'),
array('2. Smell: start with aroma families','Bring the sample close and first identify broad families: dairy, butter, yoghurt, grass, hay, nuts, animal, fermented, earthy, cellar, smoke, spices or noble mould. Only then refine when a specific reference is clear. “Toasted nut” stated confidently is more useful than forcing an exact nut.\n\nAroma intensity also matters. Tetilla can be intentionally gentle while Cabrales is powerful; judging both by “the stronger the smell, the better” makes no sense.'),
array('3. Texture: what happens before and during chewing','Touch and bite a portion. Is it elastic, crumbly, creamy, grainy, sticky, melting, moist or dry? Does it fracture into flakes or deform? Texture connects directly with moisture, fat, proteolysis and production technology.\n\nNotice how it changes at mouth temperature too. A paste that first seems firm may melt rapidly; another may break into dry particles. These differences explain why cheeses of similar aromatic intensity can feel completely different.'),
array('4. Basic tastes and aroma in the mouth','Salty, acidic, bitter and sweet sensations can appear in different proportions, along with umami and pungency. Retronasal aromas then emerge during chewing: nuts, butter, grass, cave, smoke, wine, fermentation and many others. Separating “tastes salty” from “smells smoky” improves description because these are different perceptions.\n\nA little acidity can add freshness; mild bitterness can be characteristic of vegetable-rennet cheeses. A sensation is not automatically a defect—it matters whether it fits the style and is balanced.'),
array('5. Intensity, balance and persistence','Intensity describes impact; persistence describes how long the aromatic impression remains after swallowing. A cheese can be powerful but short, or moderate yet very persistent. Balance concerns how salt, acidity, fat, aroma and rind or smoke notes integrate.\n\nThis distinction is useful when shopping. If you enjoy long finishes without aggressive impact, searching only for “strong” cheese may lead you to the wrong products. Learn which sensory dimension you actually prefer.'),
array('Taking notes without turning tasting into an exam','A home tasting sheet can use six lines: appearance, aroma, texture, basic tastes, in-mouth aromas and persistence. Add one final line about use: “eat alone”, “best on a board”, “good for cooking” or “too intense for me”. After several tastings, preference patterns become obvious.\n\nYou do not need to match official vocabulary perfectly. Consistent method matters more than naming every note with expert terminology.'),
array('How to compare two cheeses fairly','Change one variable at a time when possible. To understand milk, compare similar technologies and ages. To understand maturation, taste the same producer at two ages. To judge a wine- or paprika-treated rind, compare with a similar untreated cheese.\n\nThis avoids false conclusions such as “goat cheese is always stronger” after comparing an aged goat cheese with a fresh cow cheese. Good tasting isolates differences rather than confirming assumptions.')
),
'faq_es'=>array(array('¿Hay que comer la corteza durante una cata?','Depende del queso. Algunas cortezas forman parte del estilo y aportan información sensorial; otros recubrimientos no están destinados al consumo. Comprueba la información del productor antes de incluirla.'),array('¿El queso más intenso es el de mayor calidad?','No. Intensidad es una dimensión sensorial, no una puntuación. Equilibrio, limpieza aromática, textura y adecuación al estilo importan tanto o más.')),
'faq_en'=>array(array('Should you eat the rind during a tasting?','It depends on the cheese. Some rinds belong to the style and provide sensory information; other coatings are not intended for consumption. Check producer information first.'),array('Is the most intense cheese the highest quality?','No. Intensity is a sensory dimension, not a score. Balance, clean aroma, texture and faithfulness to style matter just as much or more.')),
'conclusion_es'=>'Una buena cata no necesita vocabulario rebuscado: necesita orden. Preparar bien la muestra, separar aroma, textura y sabor y prestar atención a la persistencia convierte una impresión vaga en información útil para elegir mejor y entender por qué un queso te gusta.',
'conclusion_en'=>'Good cheese tasting does not require elaborate vocabulary; it requires order. Preparing the sample, separating aroma, texture and taste, and paying attention to persistence turns a vague impression into useful information for choosing and understanding cheese.',
'related'=>array('como-cortar-servir-queso-temperatura-cuchillos-presentacion','como-preparar-tabla-quesos-cantidades-orden-acompanamientos','tipos-de-queso-guia-leche-maduracion-pasta-corteza-elaboracion','como-se-hace-queso-leche-cuajada-prensado-maduracion'),
'sources'=>array('https://www.boe.es/eli/es/rd/2006/09/29/1113/con','https://www.mapa.gob.es/es/alimentacion/temas/promo-alimentos/premios-alimentos/galardonados_quesos')
)
);

function emdo_cheese02_e( string $s ): string { return esc_html( $s ); }

function emdo_cheese02_category(): WP_Term {
    $term = get_category_by_slug( 'quesos' );
    if ( ! $term instanceof WP_Term ) {
        $created = wp_insert_term( 'Quesos', 'category', array( 'slug'=>'quesos', 'description'=>'Guías de compra, conservación, elaboración y cultura del queso.' ) );
        if ( is_wp_error( $created ) ) { throw new RuntimeException( $created->get_error_message() ); }
        $term = get_term( (int) $created['term_id'], 'category' );
    }
    if ( ! $term instanceof WP_Term ) { throw new RuntimeException( 'Could not resolve Quesos category.' ); }
    update_term_meta( $term->term_id, '_en_US_name', 'Cheese' );
    update_term_meta( $term->term_id, '_en_US_slug', 'cheese' );
    update_term_meta( $term->term_id, '_en_US_description', 'Buying guides, storage advice, cheesemaking and cheese culture.' );
    update_term_meta( $term->term_id, '_en_US_published', '1' );
    return $term;
}

function emdo_cheese02_image( int $category_id ): int {
    $ids = get_posts( array('post_type'=>'post','post_status'=>'publish','posts_per_page'=>20,'fields'=>'ids','category__in'=>array($category_id)) );
    foreach ( $ids as $id ) { $thumb=(int)get_post_thumbnail_id($id); if($thumb>0){return $thumb;} }
    return 0;
}

function emdo_cheese02_find_related( array $slugs, bool $spanish ): string {
    $items = array();
    foreach ( $slugs as $slug ) {
        $p = get_page_by_path( (string) $slug, OBJECT, 'post' );
        if ( ! $p instanceof WP_Post ) { continue; }
        $is_batch02 = EMDO_CHEESE_BATCH02_MARKER === (string) get_post_meta( $p->ID, '_emdo_cheese_batch02', true );
        if ( 'publish' !== get_post_status( $p ) && ! $is_batch02 ) { continue; }
        if ( $spanish ) {
            $items[] = '<li><a href="' . esc_url( '/' . $p->post_name . '/' ) . '">' . emdo_cheese02_e( get_the_title( $p ) ) . '</a></li>';
        } else {
            if ( '1' !== (string) get_post_meta( $p->ID, '_en_US_published', true ) ) { continue; }
            $en_slug = (string) get_post_meta( $p->ID, '_en_US_post_name', true );
            $en_title = (string) get_post_meta( $p->ID, '_en_US_post_title', true );
            if ( '' === $en_slug || '' === $en_title ) { continue; }
            $items[] = '<li><a href="' . esc_url( '/en/' . $en_slug . '/' ) . '">' . emdo_cheese02_e( $en_title ) . '</a></li>';
        }
    }
    if ( empty( $items ) ) { return ''; }
    return ( $spanish ? '<h2>Guías relacionadas</h2>' : '<h2>Related guides</h2>' ) . '<ul>' . implode( '', $items ) . '</ul>';
}

function emdo_cheese02_render( array $a, bool $spanish ): string {
    $lead = $spanish ? $a['lead_es'] : $a['lead_en'];
    $facts = $spanish ? $a['facts_es'] : $a['facts_en'];
    $sections = $spanish ? $a['sections_es'] : $a['sections_en'];
    $faq = $spanish ? $a['faq_es'] : $a['faq_en'];
    $conclusion = $spanish ? $a['conclusion_es'] : $a['conclusion_en'];
    $out = '<p>' . emdo_cheese02_e( $lead ) . '</p>';
    $out .= $spanish ? '<h2>Resumen rápido</h2>' : '<h2>Quick summary</h2>';
    $out .= '<table><tbody>';
    foreach ( $facts as $row ) { $out .= '<tr><th>' . emdo_cheese02_e((string)$row[0]) . '</th><td>' . emdo_cheese02_e((string)$row[1]) . '</td></tr>'; }
    $out .= '</tbody></table>';
    foreach ( $sections as $sec ) {
        $out .= '<h2>' . emdo_cheese02_e( (string) $sec[0] ) . '</h2>';
        foreach ( preg_split('/\n\n+/', (string)$sec[1]) as $p ) { if ( trim($p) !== '' ) { $out .= '<p>' . emdo_cheese02_e( trim($p) ) . '</p>'; } }
    }
    if ( ! empty( $faq ) ) {
        $out .= $spanish ? '<h2>Preguntas relacionadas</h2>' : '<h2>Related questions</h2>';
        foreach ( $faq as $qa ) { $out .= '<h3>' . emdo_cheese02_e((string)$qa[0]) . '</h3><p>' . emdo_cheese02_e((string)$qa[1]) . '</p>'; }
    }
    $out .= emdo_cheese02_find_related( (array)$a['related'], $spanish );
    $out .= $spanish ? '<h2>Conclusión</h2>' : '<h2>Bottom line</h2>';
    $out .= '<p>' . emdo_cheese02_e( $conclusion ) . '</p>';
    $out .= $spanish ? '<h2>Fuentes y referencias</h2>' : '<h2>Sources and references</h2>';
    $out .= '<ul>';
    foreach ( (array)$a['sources'] as $src ) {
        $host = (string) wp_parse_url( (string)$src, PHP_URL_HOST );
        $out .= '<li><a href="' . esc_url((string)$src) . '" rel="noopener noreferrer">' . emdo_cheese02_e($host) . '</a></li>';
    }
    $out .= '</ul>';
    return $out;
}

function emdo_cheese02_meta_title( string $s ): string {
    if ( function_exists('mb_strlen') && mb_strlen($s,'UTF-8') > 62 ) { return rtrim(mb_substr($s,0,59,'UTF-8')) . '…'; }
    return $s;
}
function emdo_cheese02_meta_description( string $s ): string {
    if ( function_exists('mb_strlen') && mb_strlen($s,'UTF-8') > 158 ) { return rtrim(mb_substr($s,0,155,'UTF-8')) . '…'; }
    return $s;
}

$term = emdo_cheese02_category();
$image_id = emdo_cheese02_image( (int)$term->term_id );
$sample = get_posts(array('post_type'=>'post','post_status'=>'publish','posts_per_page'=>1,'fields'=>'ids','category__in'=>array((int)$term->term_id)));
$author = !empty($sample) ? (int)get_post_field('post_author',(int)$sample[0]) : 1;
if ( $author <= 0 ) { $author = 1; }

// First pass: reserve all slugs and English metadata so related links can resolve cleanly.
$ids = array();
foreach ( $articles as $a ) {
    $existing = get_page_by_path( (string)$a['slug'], OBJECT, 'post' );
    if ( $existing instanceof WP_Post ) {
        if ( EMDO_CHEESE_BATCH02_MARKER !== (string)get_post_meta($existing->ID,'_emdo_cheese_batch02',true) ) {
            throw new RuntimeException( 'Refusing to overwrite existing non-batch post: ' . $a['slug'] );
        }
        $id = (int)$existing->ID;
    } else {
        $created = wp_insert_post( wp_slash(array(
            'post_type'=>'post','post_status'=>'draft','post_title'=>(string)$a['title'],'post_name'=>(string)$a['slug'],
            'post_excerpt'=>(string)$a['excerpt'],'post_author'=>$author,'post_category'=>array((int)$term->term_id),
            'comment_status'=>'closed','ping_status'=>'closed'
        )), true );
        if ( is_wp_error($created) || (int)$created <= 0 ) { throw new RuntimeException( 'Could not reserve slug: ' . $a['slug'] ); }
        $id = (int)$created;
    }
    update_post_meta($id,'_emdo_cheese_batch02',EMDO_CHEESE_BATCH02_MARKER);
    update_post_meta($id,'_emdo_editorial_position',(string)(int)$a['pos']);
    update_post_meta($id,'_en_US_post_title',(string)$a['en_title']);
    update_post_meta($id,'_en_US_post_name',(string)$a['en_slug']);
    update_post_meta($id,'_en_US_post_excerpt',(string)$a['en_excerpt']);
    update_post_meta($id,'_en_US_ready','1');
    update_post_meta($id,'_en_US_published','1');
    $ids[(string)$a['slug']] = $id;
}

// Second pass: render complete, article-specific bilingual content.
foreach ( $articles as $a ) {
    $id = (int)$ids[(string)$a['slug']];
    $es = emdo_cheese02_render($a,true);
    $en = emdo_cheese02_render($a,false);
    $updated = wp_update_post( wp_slash(array(
        'ID'=>$id,'post_status'=>'draft','post_title'=>(string)$a['title'],'post_name'=>(string)$a['slug'],
        'post_excerpt'=>(string)$a['excerpt'],'post_content'=>$es,'post_author'=>$author,
        'post_category'=>array((int)$term->term_id),'comment_status'=>'closed','ping_status'=>'closed'
    )), true );
    if ( is_wp_error($updated) ) { throw new RuntimeException( 'Spanish render failed: ' . $a['slug'] ); }
    update_post_meta($id,'_en_US_post_content',$en);
    update_post_meta($id,'_emdo_seo_title',emdo_cheese02_meta_title((string)$a['title']));
    update_post_meta($id,'_emdo_seo_description',emdo_cheese02_meta_description((string)$a['excerpt']));
    update_post_meta($id,'_en_US_seo_title',emdo_cheese02_meta_title((string)$a['en_title']));
    update_post_meta($id,'_en_US_seo_description',emdo_cheese02_meta_description((string)$a['en_excerpt']));
    if ( $image_id > 0 ) { set_post_thumbnail($id,$image_id); }
}

// Third pass: quality checks, then publish.
$published = array();
foreach ( $articles as $a ) {
    $id = (int)$ids[(string)$a['slug']];
    $es = (string)get_post_field('post_content',$id);
    $en = (string)get_post_meta($id,'_en_US_post_content',true);
    $es_words = str_word_count(wp_strip_all_tags($es));
    $en_words = str_word_count(wp_strip_all_tags($en));
    if ( $es_words < 780 || $en_words < 650 ) { throw new RuntimeException('Article too short ' . $a['slug'] . ' ES=' . $es_words . ' EN=' . $en_words); }
    if ( false !== strpos($es,'<h2>Guías relacionadas</h2><ul></ul>') || false !== strpos($en,'<h2>Related guides</h2><ul></ul>') ) {
        throw new RuntimeException('Empty related guides block: ' . $a['slug']);
    }
    if ( empty($a['faq_es']) && false !== strpos($es,'<h2>Preguntas relacionadas</h2>') ) { throw new RuntimeException('Unexpected ES FAQ: '.$a['slug']); }
    if ( empty($a['faq_en']) && false !== strpos($en,'<h2>Related questions</h2>') ) { throw new RuntimeException('Unexpected EN FAQ: '.$a['slug']); }
    $result = wp_update_post(array('ID'=>$id,'post_status'=>'publish'),true);
    if ( is_wp_error($result) ) { throw new RuntimeException('Publish failed: '.$a['slug']); }
    clean_post_cache($id);
    $published[] = array('position'=>(int)$a['pos'],'id'=>$id,'slug'=>(string)$a['slug'],'en_slug'=>(string)$a['en_slug'],'es_words'=>$es_words,'en_words'=>$en_words,'image_id'=>(int)get_post_thumbnail_id($id));
}

echo "EMDO_CHEESE_BATCH02_BEGIN\n";
echo wp_json_encode(array('marker'=>EMDO_CHEESE_BATCH02_MARKER,'count'=>count($published),'category_id'=>(int)$term->term_id,'category'=>$term->name,'posts'=>$published),JSON_UNESCAPED_SLASHES|JSON_UNESCAPED_UNICODE) . "\n";
echo "EMDO_CHEESE_BATCH02_END\n";
